      const now=new Date(),next=result.nextDueDate||dateOnly(now),updated={...sub,companyName,pendingPlan:newPlan,price:PLAN_CATALOG[newPlan].price,status:result.status||'pending',paymentMethod:method,nextChargeAt:next,lastPaymentStatus:result.status==='active'?'paid':'pending',planLockUntil:result.downgradeLockedUntil,planChangedAt:now.toISOString(),asaasSubscriptionId:result.subscriptionId,billingCustomer:{name,document:doc,email}};
      localStorage.setItem('forgepets_active_subscription',JSON.stringify(updated));
      close();renderNav();render();
