      const openCardModal=()=>{modal('Pagamento com cartão',`<div class="payment-experience card-payment-modal"><header class="payment-hero"><span class="payment-hero-icon">✓</span><div><h2>Dados enviados com segurança</h2><p>Estamos confirmando a assinatura com o Asaas.</p></div></header><div class="payment-summary-grid"><div><small>Plano</small><strong>${escapeHtml(newPlan)}</strong></div><div><small>Mensalidade</small><strong>${money(PLAN_CATALOG[newPlan].price)}</strong></div><div><small>Próxima cobrança</small><strong>${next?new Date(`${next}T12:00:00`).toLocaleDateString('pt-BR'):'—'}</strong></div><div><small>Forma</small><strong>Cartão de crédito</strong></div></div><div id="livePaymentStatus" class="payment-status waiting"><span class="payment-status-icon">⌛</span><div><b>Confirmando assinatura</b><small>A ativação acontece automaticamente.</small></div></div><div class="payment-security">🔒 Seus dados são processados diretamente pelo Asaas.</div></div>`,closeCard=>closeCard(),'Fechar');setTimeout(()=>{preparePaymentModal();startStatusWatch();},0);};
      if(method==='pix') setTimeout(async()=>{if(result.pix?.encodedImage&&result.pix?.payload)return openPixModal(result.pix);modal('Gerando PIX',`<div class="pix-generating"><span class="pix-loader"></span><b>Preparando seu QR Code…</b><small>A assinatura já foi criada. Aguarde alguns segundos.</small></div>`,closeWait=>closeWait(),'Fechar');for(let attempt=0;attempt<10;attempt++){await new Promise(resolve=>setTimeout(resolve,1200));try{const check=await cloud.request('/api/forge/subscription?pix=1');if(check.ready&&check.pix?.encodedImage){document.querySelector('#modalRoot').innerHTML='';return setTimeout(()=>openPixModal(check.pix),60);}}catch{}}setModalError('A assinatura foi criada, mas o QR Code ainda não ficou disponível. Abra novamente a área do plano em alguns instantes.');},80);
