  setTimeout(()=>{document.querySelectorAll('input[name="subscriptionMethod"]').forEach(input=>input.addEventListener('change',()=>{document.querySelectorAll('.payment-option').forEach(x=>x.classList.toggle('selected',x.querySelector('input').checked));const selected=document.querySelector('input[name="subscriptionMethod"]:checked')?.value;$('#cardFields').style.display=selected==='card'?'grid':'none';}));},0);
